  "auth.aboutLink": "Kuhusu Luminous StockHaven",
  'about.bookshopLeadIn': "Imetengenezwa na biashara ndogo ile ile inayoendesha duka letu la vitabu:",
  "about.eyebrow": "Kuhusu Luminous StockHaven",
  "about.pageTitle": "Luminous StockHaven — Kuhusu Sisi",
  "about.founderHeading": "📖 Kuhusu Mwanzilishi",
  "about.founder.p1": "Habari, mimi ni Concepcion, mwanzilishi wa Luminous StockHaven.",
  "about.founder.p2": "Sitoki katika kampuni kubwa ya teknolojia, na sikai katika ofisi ya shirika. Mimi ni mmiliki mdogo wa rejareja, kama wewe tu. Ninaendesha maduka matano ya mtandaoni yanayobobea katika vitabu na vifaa vilivyotengenezwa kwa mikono kwa wapenda vitabu.\nKama wauzaji wengi huru wa rejareja, nilifika mahali pa kuvunjika nilipojaribu kusimamia hesabu ya bidhaa katika maeneo mengi, kufuatilia ISBN za wachapishaji pamoja na SKU zangu za mikono, na kushughulikia maagizo ya wasambazaji kwa majedwali magumu. Nilipotafuta programu ya kunisaidia, nilijaribu chaguo sita tofauti. Kila moja ilikuwa haijakamilika kabisa, inachanganya sana, au ya kunyonya — ikitoza mamia ya dola kwa mwezi kwa zana za msingi.",
  "about.founder.p3": "Nikiwa nimechoshwa na sekta inayowanyonya waumbaji huru, niliamua kujenga suluhisho langu mwenyewe. Nilijenga Luminous StockHaven kwa ulazima, ili kuendesha biashara zangu mwenyewe kwa usafi, ufanisi, na kwa amani kamili ya akili.",
  "about.founder.p4": "Niliamua kufungua jukwaa hili kwa umma kwa bei ya uaminifu na nafuu, kwa sababu kila mmiliki mdogo wa biashara anastahili zana zinazofanya kazi kweli bila kuhatarisha mapato yake. Sisi ni wa kumilikiwa kwa uhuru, tunalinda jamii yetu kwa nguvu, na tumejengwa na muuzaji wa rejareja, kwa wauzaji wa rejareja.",
  "notice.ariaLabel": "Ilani ya alama za biashara na hakimiliki",
  "notice.heading": "🛡️ Imejengwa kwa Wauzaji wa Rejareja, Haina Bei kwa Tai wa Mashirika",
  "notice.intro": "Nilijenga programu hii kwa sababu naendesha maduka 5 na nilikuwa nimechoka kudanganywa na programu zinazochanganya za mamia ya dola. Programu hii ilijengwa kuwalinda wasanii huru, mafundi, wauzaji wa vitabu, na maduka ya karibu.",
  "notice.legalHeading": "ILANI YA KISHERIA KWA WASHINDANI NA WAIGAJI:",
  "notice.legalBody": "Tunafuatilia soko kwa bidii. Jaribio lolote la kukwapua jukwaa letu, kuiga michakato yetu ya kipekee, au kukiuka mali yetu ya kiakili litakabiliwa na hatua za kisheria za haraka na kali.",
  "notice.acquisitionHeading": "KWA MAKAMPUNI YA UNUNUZI NA MADALALI:",
  "notice.acquisitionBody": "Usinitumie barua pepe. Usinitumie ujumbe. Usinipendekezee 'kutoka kwa kimkakati'. Unaweza kutoa maelfu, mamilioni, mabilioni, au matrilioni — jibu ni Hapana. Hutainunua programu hii ili tu kupandisha bei kwa wauzaji wenzangu. Kila barua pepe ya ununuzi isiyoombwa itawekwa alama ya taka mara moja, na kikoa chako kitazuiwa kabisa kutoka kwenye jukwaa letu. Okoa pumzi yako.",
