  "plans.backToWelcome": "Rudi kwenye karibu",
  "plans.eyebrow": "Mipango na vipengele",
  "plans.title": "Linganisha mipango ya StockHaven",
  "plans.intro": "Akaunti moja, mpango wowote utakaochagua — Business inashughulikia hadi biashara tano. Bei ni za kila mwezi kwa dola za Marekani, na wateja wapya wa tovuti wanaostahiki wanaweza kupokea jaribio moja la siku saba katika Essentials na Business. Kuboresha usajili uliopo wa Essentials hadi Business hakuuanzishi upya jaribio wala hakuundi jaribio jingine la bure. Bei za mipango ya tovuti ni kabla ya kodi zinazohusika, ikiwa zipo. Tozo yako kamili itaonyeshwa kabla ya kuidhinisha usajili.",
  "plans.availableAtLaunch": "Inapatikana wakati wa uzinduzi wa simu",
  "plans.yourPlan": "Mpango wako",
  "plans.currentPlan": "Mpango wa sasa",
  "plans.changePlan": "Badilisha mpango",
  "plans.subscribe": "Jisajili",
  "plans.featureHeader": "Kipengele",
  "plans.perMonthShort": "/mwezi",
  "plans.included": "Imejumuishwa",
  "plans.notIncluded": "Haijajumuishwa",
  "plans.mobileIncludedNote": "Mipango yote miwili ya tovuti inajumuisha mwenza wa simu, kwa hivyo msajili wa tovuti halipi kamwe ada ya kila mwezi ya simu pia.",
  "plans.priceNote": "Essentials ni $14.99/mwezi pamoja na kodi zinazohusika, ikiwa zipo. Business ni $29.99/mwezi pamoja na kodi zinazohusika, ikiwa zipo. Kodi yoyote inayohitajika huamuliwa wakati wa malipo ya mtoa huduma na lazima ionekane katika jumla ya mwisho kabla ya malipo. Ukurasa huu wa ulinganisho si nukuu ya kodi wala idhini ya malipo.",
  "plans.mobilePriceNote": "Mpango wa simu pekee ni $4.99/mwezi kwa bei yake ya msingi iliyokusudiwa ya Marekani. App Store au Google Play huonyesha bei halisi ya usajili ya eneo lako na kodi zozote zinazohusika kabla ya ununuzi. Posho zake za bidhaa, tovuti na wafanyakazi huwekwa wakati wa uzinduzi, kando na viwango vya tovuti.",
  "plans.planChangeNote": "Mabadiliko ya mpango wa tovuti lazima yathibitishwe na mtoa huduma wa malipo. Bei mpya, tarehe ya kuanza kutumika na mgawo wowote wa uwiano utaelezewa kabla ya mabadiliko kuidhinishwa. Kuboresha hakupaswi kuunda usajili wa pili.",
  "plans.providerNote": "Bei, tozo na majaribio hushughulikiwa na mtoa huduma unayejisajili kupitia kwake — App Store, Google Play, tovuti au Shopify — kamwe si kwa ukurasa huu.",
