  "upgrade.intro": "Wateja wapya wanaostahiki wanaweza kupokea jaribio moja la siku {days} kwa akaunti, si jaribio moja kwa mpango. Kubadilisha kutoka Essentials hadi Business hakuanzishi kamwe jaribio jingine la bure. Uko kwenye",
