  "upgrade.pastDueTitle": "Malipo yamechelewa",
  "upgrade.pastDueBody": "Malipo yako ya mwisho hayakufanikiwa, kwa hivyo usajili huu umechelewa. Unabaki na matumizi kamili kwa siku 14 tangu malipo yaliyoshindwa unapoyarekebisha. Ikiwa hayatarekebishwa, usajili utaghairiwa, eneo la kazi litakuwa la kutazama tu kwa siku 15, na kisha akaunti na taarifa zake zote zitafutwa. Kulipa wakati wowote kabla ya kufutwa kunarudisha kila kitu. Sasisha njia yako ya malipo hapa chini. Ikiwa unahitaji msaada, tuma barua pepe kwa",
