  "billing.cancel.appStoreNote": "Ikiwa utawahi kujisajili kupitia Google Play au Apple App Store, unaweza kuhitaji kuughairi kupitia mipangilio ya usajili ya duka hilo. Kidirisha hiki hakiwezi kusitisha malipo ya duka la programu. Kuondoa programu au kufuta akaunti yako ya StockHaven hakughairi usajili wa duka.",
