  "billing.dryRun.title": "Essentials → Business — uigaji wa mazoezi",
  "billing.dryRun.body": "Fanya mazoezi ya sheria zilizopendekezwa za kuboresha kwa kutumia rekodi za kubuni kabisa katika kivinjari hiki. Hii haisomi wala haibadilishi TEST yako halisi — sampuli ya Pajama Pants, eneo lako la sasa la kazi la Business, Stripe, majaribio, usajili au hesabu ya bidhaa.",
