  "reports.missingMoney": "Vitengo {units} katika mwonekano huu havina {label} iliyorekodiwa. Pesa zinazokosekana hazichukuliwi kamwe kama sifuri — huachwa nje ya takwimu badala ya kuhesabiwa kama bure. Ongeza takwimu kwenye bidhaa hizo na jumla hujazwa.",
  "reports.movementsCapped": "Maingizo mapya zaidi tu {cap} ya daftari yalisomwa, kwa hivyo mienendo ya zamani kuliko hii haiko katika jumla. Punguza kipindi ili kuona takwimu kamili kwa muda fulani.",
  "reports.footnote": "Mauzo hutumia bei ya sasa ya rejareja ya kila bidhaa, risiti hutumia gharama iliyorekodiwa hisa ilipofika, na hasara hutumia gharama ya sasa ya kitengo. Pesa zinazokosekana hazichukuliwi kamwe kama sifuri — acha takwimu tupu hadi ijulikane. Ripoti ni mwonekano, si hati: hakuna kinachoandikwa katika rekodi zako unapoendesha moja.",
