  "valuation.footnote": "Thamani ya gharama hutumia gharama ya sasa ya kitengo cha kila bidhaa, kwa hivyo kupokea kwa bei mpya huthamini upya rafu nzima. Vitengo vilivyohifadhiwa bado huhesabiwa hapa — vipo, vimeahidiwa tu kwa agizo. Pesa zinazokosekana hazichukuliwi kamwe kama sifuri; acha sehemu tupu hadi takwimu ijulikane.",
