  "settings.deletion.checkError": "Imeshindwa kukagua maombi yaliyopo kwa sasa. Bado unaweza kujaribu kuwasilisha ombi.",
  "settings.deletion.confirmError": "Hatukuweza kuthibitisha ombi lako la kufutwa. Tafadhali jaribu tena.",
