  "settings.deletion.submitError": "Imeshindwa kuwasilisha ombi lako. Tafadhali jaribu tena.",
  "settings.details.address": "Anwani",
  'settings.details.taxRate': 'Kiwango changu cha kodi',
  'settings.details.taxRateHint': 'Kiweke mara moja. Kila agizo jipya la mauzo hujaza kodi yake kutoka kiwango hiki — bado unaweza kubadilisha kodi kwenye agizo moja.',
  "settings.details.taxMode": "Jinsi maagizo yanavyopata kodi yao",
  "settings.details.taxModeFixed": "Kiwango changu kisichobadilika",
  "settings.details.taxModeAutomatic": "Kiotomatiki — kulingana na jimbo la mteja",
  "settings.details.taxModeHint": "Hali isiyobadilika hutumia kiwango chako kwenye kila agizo jipya. Hali ya kiotomatiki hujaza kodi ya agizo jipya kwa kiwango cha msingi cha jimbo la mteja mara tu jimbo linapokuwa kwenye agizo, na kuijaza tena jimbo likibadilika. Hivi ni viwango vya msingi vya majimbo — kodi za mitaa zinaweza kuongeza zaidi. Agizo lisilo na jimbo, au kutoka nje ya Marekani, hutumia kiwango chako kisichobadilika hapo juu.",
  'settings.details.gs1Prefix': "Kiambishi awali cha kampuni ya GS1",
  'settings.details.gs1PrefixHint': "Ikiwa tu una leseni ya kiambishi awali kutoka GS1. Weka mara moja na kitengeneza misimbo cha fomu ya bidhaa kinaweza kutengeneza misimbo halisi ya rejareja ya UPC na EAN kutoka nambari zako mwenyewe — kila moja hutumika mara moja tu na haitumiki tena kamwe. Iache tupu ikiwa huna; programu haitungi kiambishi awali kamwe.",
  'settings.details.gs1LearnMore': "Mpya kwa GS1? Ukiishi katika nchi yako mwenyewe, tumia kiungo chake kujifunza zaidi; ukiishi Marekani, tumia kiungo cha GS1 US.",
