  "settings.pastDue.body": "Malipo yako ya mwisho hayakufanikiwa. Unabaki na matumizi kamili kwa siku 14 tangu malipo yaliyoshindwa unapoyarekebisha. Ikiwa hayatarekebishwa, usajili utaghairiwa, eneo la kazi litakuwa la kutazama tu kwa siku 15, na kisha akaunti na taarifa zake zote zitafutwa. Kulipa wakati wowote kabla ya kufutwa kunarudisha kila kitu. Ikiwa huna uhakika wa la kufanya, wasiliana na usaidizi kupitia theluminousbookshop@outlook.com.",
