  "recovery.emailMeCodeHint": "Ikiwa uliweka barua pepe ya akiba, tutatuma msimbo wa tarakimu 6 huko. Kulinda akaunti yako, ukurasa huu daima hujibu kwa njia ile ile — ikiwa msimbo ulitumwa au la.",
  "recovery.codeSent": "Ikiwa barua pepe yako ya akiba iko kwenye faili, msimbo wa tarakimu 6 uko njiani huko sasa. Unaisha baada ya dakika 10.",
