  "recovery.changeIntro": "Umeingia — kwa hatua moja pekee: chagua barua pepe mpya kwa akaunti yako. Duka lako, hesabu yako na ufikiaji wa timu yako vyote vinahama nayo.",
  "recovery.doneBody": "Barua pepe ya akaunti yako imebadilishwa na kuingia huku sasa ni kuingia kwako kwa kawaida tena. Karibu tena.",
