  "pos.square.help": "Unganisha Square na kila uuzaji kwenye tili hutoa vipengee vyake kutoka kwenye hisa hapa yenyewe — hakuna cha kuandika mwishoni mwa siku.",
  "pos.square.notConfigured": "Miunganisho ya Square haijawashwa bado. Uingizaji wa CSV hapa chini hufanya kazi leo.",
  "pos.subtitle": "Unganisha tili yako, na uuzaji kwenye rejista hutoa kipengee kutoka kwenye hisa hapa yenyewe. Hakuna kinachohesabika mara mbili kamwe.",
  "pos.title": "Miunganisho ya tili",
  "pos.webhookPending": "Webhooks za mauzo hazijawashwa bado kwa upande wetu — miunganisho imehifadhiwa, na mauzo huanza kufika wakati zinapowashwa.",
  "training.lessons.owner-pos-connect-shopify.step1": "Miunganisho ya tili ni sehemu ya mpango wa Business. Mauzo ya Shopify POS ni maagizo ya Shopify, kwa hivyo muunganisho ni kwa kila duka: katika Shopify, unda programu ya desturi kwa duka lako na unakili tokeni yake ya ufikiaji. Kwenye ukurasa wa Miunganisho ya tili, bandika kikoa cha duka lako (kama your-store.myshopify.com) na tokeni.",
  "training.lessons.owner-pos-connect-shopify.step2": "Tokeni huhifadhiwa kwenye seva pekee — kamwe haionyeshwi tena, hata kwako. Ikiwa utabandika mpya, hubadilisha ya zamani tu.",
  "training.lessons.owner-pos-connect-shopify.step3": "Chagua ni eneo lipi kati ya maeneo yako ambalo mauzo ya duka hili hutoka, ikiwa una zaidi ya moja. Kisha kila agizo — kwenye tili ya Shopify au mtandaoni — hutoa vipengee vyake kutoka kwenye hisa hapa yenyewe.",
  "training.lessons.owner-pos-connect-shopify.step4": "Duka moja huunganishwa na eneo moja la kazi hapa. Ikiwa kikoa tayari kimeunganishwa mahali pengine, programu husema hivyo waziwazi badala ya kukishiriki.",
  "training.lessons.owner-pos-connect-shopify.title": "Kuunganisha Shopify POS",
  "training.lessons.owner-pos-connect-square.step1": "Miunganisho ya tili ni sehemu ya mpango wa Business. Fungua Miunganisho ya tili (katika menyu ya Mauzo) na uguse Unganisha kwenye kadi ya Square. Utafika kwenye ukurasa wa Square mwenyewe kuidhinisha muunganisho — programu kamwe haioni nenosiri lako la Square.",
  "training.lessons.owner-pos-connect-square.step2": "Ukirudi kwenye programu, kadi huonyesha Imeunganishwa. Ikiwa duka lako lina zaidi ya eneo moja, chagua lipi mauzo ya tili hii hutoka; vinginevyo mauzo hutoka kwenye eneo lako la kwanza.",
  "training.lessons.owner-pos-connect-square.step3": "Kuanzia hapo, kila uuzaji wa Square hutoa vipengee kutoka kwenye hisa hapa yenyewe. Uza kitu kimoja kwenye tili na uangalie orodha ya Mauzo ya hivi karibuni kwenye ukurasa ule ule: uuzaji hufika ndani ya muda mfupi, umewekwa kuwa umehesabiwa.",
  "training.lessons.owner-pos-connect-square.step4": "Uuzaji kamwe hauwezi kuhesabika mara mbili — ikiwa Square itatuma uuzaji ule ule tena, programu huutambua na haibadilishi chochote. Kutenganisha kuko kwenye kadi ile ile, na husimamisha ulinganishaji mara moja.",
  "training.lessons.owner-pos-connect-square.title": "Kuunganisha Square: mauzo yanayosogeza hisa yako kwa ajili yako",
  "training.lessons.owner-pos-csv.step1": "Tili yoyote inayoweza kuhamisha faili ya mauzo bado inaweza kulisha hesabu yako. Hamisha mauzo ya siku kama CSV yenye safu hizi: sale_id, sold_at, sku_or_barcode, quantity — item_name na location husaidia, lakini si lazima.",
  "training.lessons.owner-pos-csv.step2": "Pakia faili kwenye ukurasa wa Miunganisho ya tili. Kila sale_id hurekodiwa mara moja: kupakia faili ile ile tena kesho hakubadilishi chochote, huripoti tu nakala.",
  "training.lessons.owner-pos-csv.step3": "Safu ambazo programu haiwezi kutumia kamwe hazirukwi kimya kimya — safu isiyo na sale_id, au kiasi ambacho si namba, huorodheshwa kwako na namba yake ya safu na sababu.",
  "training.lessons.owner-pos-csv.step4": "Vipengee hulinganishwa kwa SKU au msimbo pau, kama tu tili ya moja kwa moja. Cho chote kisicholingana husubiri kwenye skrini ya ulinganishaji, kama uuzaji mwingine wowote.",
  "training.lessons.owner-pos-csv.title": "Hakuna API ya tili? CSV ya mwisho wa siku",
  "training.lessons.owner-pos-mapping.step1": "Kipengee cha tili hulingana na bidhaa zako kwa SKU au msimbo pau. Uuzaji unapokuja na kipengee ambacho programu haijakiona kamwe, kipengee hicho HUSHIKILIWA — hakuna hisa inayosogea, na uuzaji husubiri kwenye ukurasa wa Miunganisho ya tili chini ya Vipengee vinavyosubiri kulinganishwa.",
  "training.lessons.owner-pos-mapping.step2": "Chagua bidhaa gani kati ya bidhaa zako kipengee hicho kweli ni, na uhifadhi. Ulinganisho huo hukumbukwa kwa kudumu: kila uuzaji wa baadaye wa kipengee hicho huhesabika wenyewe.",
  "training.lessons.owner-pos-mapping.step3": "Baada ya kuhifadhi, gusa Tumia kwa mauzo yaliyoshikiliwa kuhesabu mauzo yaliyokuwa yakisubiri — huandika mienendo yao ya hisa wakati huo huo, kwa rejeleo la uuzaji lenyewe.",
  "training.lessons.owner-pos-mapping.step4": "Ikiwa uuzaji ulioshikiliwa unaomba zaidi ya yaliyopo rafu, unabaki umewekwa kuwa hisa haitoshi badala ya kuendesha hesabu kuwa hasi. Jaza tena, kisha tumia tena kutoka skrini ile ile.",
  "training.lessons.owner-pos-mapping.title": "Kipengee cha tili kisipolingana: skrini ya ulinganishaji",
  "training.lessons.owner-pos-sales-list.step1": "Orodha ya Mauzo ya hivi karibuni kwenye ukurasa wa Miunganisho ya tili huonyesha kila uuzaji tili zako zilizotuma: tili gani, namba ya uuzaji, lini, jumla kama tili ilivyoripoti, na kilichotokea kwa kila kipengee.",
  "training.lessons.owner-pos-sales-list.step2": "Imehesabiwa inamaanisha hisa ilisogea. Sehemu imehesabiwa inamaanisha baadhi ya vipengee vilihesabika na baadhi vinasubiri au ni pungufu — fungua uuzaji kuona vipi, kwa maneno wazi.",
  "training.lessons.owner-pos-sales-list.step3": "Imeshikiliwa inamaanisha hakuna katika uuzaji huo kilichohesabika bado: kipengee kinahitaji kulinganishwa (angalia somo la ulinganishaji), rafu haikubeba ya kutosha, au uuzaji ulifika duka halikuwa kwenye mpango wa Business. Yote matatu yanaweza kurekebishwa kutoka ukurasa ule ule — uuzaji ulioshikiliwa kwa mpango huhesabika kutoka hapa duka linaporudi kwenye Business — na hakuna kinachopotea kimya kimya kamwe.",
  "training.lessons.owner-pos-sales-list.step4": "Kila uuzaji uliohesabiwa huandika ingizo la kawaida la Kimeuzwa katika historia yako ya hisa kwa rejeleo linalotaja tili na uuzaji — kwa hivyo ukurasa wako wa Mienendo na tili yako daima husema hadithi ile ile.",
  "training.lessons.owner-pos-sales-list.title": "Kusoma mauzo yako ya tili",
  "training.lessons.staff-pos-till-sales.step1": "Ikiwa duka lako liko kwenye mpango wa Business na limeunganisha tili yake (Square au Shopify POS), kila uuzaji kwenye rejista hutoa kipengee kutoka kwenye hisa hapa yenyewe — hakuna kuchanganua kutoka, hakuna kukiandika baadaye.",
  "training.lessons.staff-pos-till-sales.step2": "Unaweza kuiona ikitokea kwenye ukurasa wa Miunganisho ya tili: kila uuzaji huonyesha kilichouzwa, vingapi, na ikiwa kilihesabika. Uuzaji uliohesabika huonekana kama umehesabiwa, kwa maneno wazi.",
  "training.lessons.staff-pos-till-sales.step3": "Wakati mwingine uuzaji HUSHIKILIWA badala yake: tili iliuza kitu ambacho programu haikuweza kukilinganisha na bidhaa bado. Hakuna kilichotolewa kutoka kwenye hisa — uuzaji husubiri hadi mmiliki au meneja alinganishe kipengee hicho mara moja (skrini ya ulinganishaji). Baada ya hapo, huhesabika, na uuzaji unaofuata wa kipengee kile kile hulingana wenyewe.",
  "training.lessons.staff-pos-till-sales.step4": "Ikiwa uuzaji ulioshikiliwa unahusu kitu ulichouza tu, mwambie meneja wako au mmiliki — ulinganisho mmoja wa haraka huurekebisha kwa kudumu. Kamwe usirekebishe hisa kwa mkono kufidia uuzaji ulioshikiliwa; hiyo ingeuhesabu mara mbili ukilinganishwa.",
  "training.lessons.staff-pos-till-sales.title": "Tili inapouza, hisa yako husogea yenyewe",
