  "print.senderAddressLabel": "Anwani yako (mtumaji)",
  "print.shippingNote": "Ikiwa oda ina anwani ya kutuma, hujazwa kutoka kwenye oda. Unachokiandika hapa huchapishwa mara moja na hakihifadhiwi kamwe.",
  "print.carrier.title": "Lebo ya mtoa huduma wako",
  "print.carrier.desc": "Nunua posta kutoka kwa mtoa huduma, kama unavyofanya leo — programu hii haiuzi posta kamwe, kwa hivyo bei unayolipa daima ni bei ya mtoa huduma mwenyewe. Hifadhi faili ya lebo hapa na inabaki kwenye agizo hili milele: rekodi yako, mkononi ikiwa chochote kitatokea.",
  "print.carrier.none": "Hakuna lebo ya mtoa huduma iliyohifadhiwa kwa agizo hili bado.",
