  "print.carrier.badType": "Faili hilo halitafanya kazi — chagua lebo ya PDF, PNG, au JPG.",
  "print.carrier.failed": "Lebo haikuweza kuhifadhiwa. Hakuna kilichobadilika — jaribu tena.",
