  "print.carrier.pickOrderFirst": "Chagua agizo hapo juu, kisha hifadhi lebo ya mtoa huduma wake hapa.",
  'print.carrier.pickFirstTap': "Chagua agizo hapo juu kwanza — kisha kitufe hiki huhifadhi lebo ya mtoa huduma kwenye agizo hilo.",
  "print.style.title": "Mtindo wa hati",
  "print.style.desc": "Fanya hati zako ziwe zako. Chaguo hizi hupamba ankara, risiti, hati ya upakiaji, hati za urejeshaji, karatasi za bidhaa, karatasi za kuhesabu, na orodha za kuchukua — na hukumbukwa kwa biashara yako.",
  "print.style.logoLabel": "Nembo yako",
  "print.style.logoOn": "Nembo yako huchapishwa juu ya hati zako.",
  "print.style.logoOff": "Hakuna nembo bado. Ongeza moja katika Mipangilio na itachapishwa juu ya hati zako.",
  "print.style.color": "Chapisha kwa rangi",
  "print.style.colorHint": "Imewashwa: nembo, picha, na fremu yako huchapishwa kwa rangi. Imezimwa: kila kitu huchapishwa kwa nyeusi-na-nyeupe safi, ikiokoa wino.",
  "print.style.font": "Fonti ya hati",
