  "profile.title": "Picha yako ya wasifu",
  "profile.ownerDesc": "Picha yako na jina ambalo timu yako inakufahamu kwalo. Picha yako mwenyewe huonekana mara moja — hakuna idhini inayohitajika.",
  "profile.memberDesc": "Picha yako huonekana kando ya jina lako mara mmiliki anapoidhinisha. Hadi wakati huo, herufi za kwanza za jina lako tu ndizo zinazoonekana.",
