  "plansLib.includes.profilePhotos": "Picha za wasifu kwa timu yako yote, zilizoidhinishwa na mmiliki",
  "apiErrors.notFound.photoFound": "Picha haikupatikana.",
  "apiErrors.profileOwnerNameOnly": "Mmiliki wa biashara pekee ndiye anayeweza kuweka jina la mmiliki.",
  "apiErrors.profilePhotosApproveOwnerOnly": "Mmiliki wa biashara pekee ndiye anayeweza kuidhinisha picha za timu.",
  "apiErrors.profilePhotosNoneWaiting": "Mwanatimu huyo hana picha inayongoja idhini.",
  "apiErrors.profileOwnerNameTooLong": "Weka jina lako liwe herufi 80 au chache zaidi.",
  "training.lessons.your-profile-photo.title": "Picha yako ya wasifu",
  "training.lessons.your-profile-photo.step1": "Picha yako huonekana kando ya jina lako juu ya programu, kwenye ukurasa wa Wafanyakazi, na kando ya ujumbe wako — mara mmiliki anapoidhinisha. Hadi wakati huo, herufi za kwanza za jina lako tu ndizo zinazoonekana.",
  "training.lessons.your-profile-photo.step2": "Fungua Mipangilio na utafute Picha yako ya wasifu. Chagua picha yako na uitume. Inakwenda kwa mmiliki ili aidhinishe — haionekani popote inapongoja.",
  "training.lessons.your-profile-photo.step3": "Mmiliki anapoidhinisha, kengele yako hulia na picha yako huanza kuonekana. Ikiwa haikuidhinishwa, chagua picha tofauti na uitume hiyo badala yake.",
  "training.lessons.your-profile-photo.step4": "Kubadilisha picha yako hufanya kazi kwa njia ileile: mpya inasubiri idhini, na picha yako ya sasa inabaki mahali pake hadi mpya iidhinishwe. Ikiwa mabadiliko hayakuidhinishwa, unabaki na ile nyingine yako.",
  "training.lessons.owner-profile-photos.title": "Picha za wasifu na jina lako",
  "training.lessons.owner-profile-photos.step1": "Picha ya kila mtu huonekana kando ya jina lake juu ya programu, kwenye ukurasa wako wa Wafanyakazi, na kando ya ujumbe wake. Picha ya mwanatimu haionekani popote hadi utakapoidhinisha — idhini ni yako peke yako, na hakuna anayeweza kuidhinisha picha yake mwenyewe.",
  "training.lessons.owner-profile-photos.step2": "Mtu anapotuma picha, kengele yako hulia. Fungua ukurasa wa Wafanyakazi ili kuiona, kisha chagua Idhinisha au Usidhinishe. Ikiwa hutoidhinisha, mtu huyo anaambiwa kuchagua picha nyingine.",
  "training.lessons.owner-profile-photos.step3": "Ikiwa mtu anabadilisha picha yake, mpya inasubiri idhini yako kwa njia ileile. Picha yake ya sasa inabaki mahali pake inapongoja — na inabaki ikiwa hutoidhinisha mabadiliko hayo.",
  "training.lessons.owner-profile-photos.step4": "Picha yako mwenyewe haihitaji idhini: iweke katika Mipangilio, chini ya Picha yako ya wasifu. Kadi ileile inashikilia jina lako — jina unaloweka hapo linachukua nafasi ya neno Mmiliki kila mahali timu yako inapolina, katika programu na katika Ujumbe.",
  "payroll.dd.corrected": "Fomu iliyorekebishwa",
  "payroll.dd.correctedDone": "Maelezo yako yaliyorekebishwa yametumwa kwa mmiliki.",
  "payroll.dd.correctionNotice": "Mmiliki amekurudishia fomu yako ili uweze kuirekebisha. Angalia kila tarakimu, saini, na utume tena.",
  "payroll.dd.correctionWaiting": "Imerudishwa — inasubiri fomu yao iliyorekebishwa",
  "payroll.dd.fixHelp": "Ikiwa tarakimu si sahihi, rekebisha maelezo yako na utume fomu tena. Fomu yako mpya iliyosainiwa inachukua nafasi ya ile ya zamani, na mmiliki anaarifiwa kwamba imerekebishwa.",
  "payroll.dd.fixMistake": "Rekebisha kosa",
  "payroll.dd.form.historyTitle": "Fomu zilizosainiwa awali",
  "payroll.dd.form.ownerOnlyNote": "Ni wewe tu, mmiliki, unayeweza kufungua fomu hii. Inaonyesha namba kamili za benki na saini ya mwanachama.",
  "payroll.dd.form.replacedOn": "Ilibadilishwa tarehe {date}",
  "payroll.dd.form.signedOn": "Ilisainiwa tarehe {date}",
  "payroll.dd.sendBack": "Rudisha kwa marekebisho",
  "payroll.dd.sendBackDone": "Imerudishwa kwa {name} — sasa wanaweza kurekebisha maelezo yao.",
  "payroll.dd.signHelp": "Andika jina lako, kisha chagua jinsi saini yako itakavyoonekana. Hii ni saini yako ya kielektroniki — inawekwa kwenye fomu yako ya amana ya moja kwa moja kama inavyoonyeshwa hapa.",
  "payroll.dd.signName": "Jina lako — linakuwa saini yako",
  "payroll.dd.signStyle": "Mtindo wa saini",
  "payroll.dd.signTitle": "Saini fomu yako",
  "payroll.dd.signedAs": "Ilisainiwa kama {name} tarehe {date}",
  "payroll.dd.styleItalic": "Italiki",
  "payroll.dd.styleScript": "Mwandiko wa mkono unaotiririka",
  "payroll.dd.styleSimple": "Rahisi na wazi",
  "payroll.dd.viewForm": "Tazama fomu iliyosainiwa",
  "payroll.profile.address": "Anwani ya nyumbani",
  "payroll.profile.name": "Jina kamili",
  "payroll.profile.noAddress": "Hakuna anwani ya nyumbani iliyorekodiwa bado.",
  "payroll.profile.note": "Maelezo haya hutumiwa kwa mshahara wako na fomu za kodi, na ni wewe tu unayeweza kuyaona hapa. Ikiwa chochote kinahitaji kubadilishwa, muulize mmiliki au meneja wako — wao ndio wanaoweza kuyasasisha.",
  "payroll.profile.title": "Maelezo yako yaliyorekodiwa",
  "payroll.stubs.print": "Chapisha / pakua",
  "apiErrors.invalidValue.signYourForm": "Andika jina lako ili kusaini fomu yako ya amana ya moja kwa moja.",
  "apiErrors.invalidValue.chooseSignatureStyle": "Chagua mtindo wa saini.",
  "apiErrors.invalidValue.noDdDetailsYet": "Mwanachama huyo wa timu bado hajatuma maelezo yake.",
  "training.lessons.owner-dd-setup.step5": "Kinachowasili ni fomu iliyofungwa na kusainiwa: kutoka safu ya mtu huyo katika Malipo ya mishahara unaweza kuifungua kusoma namba kamili, kuichapisha au kuhifadhi nakala — huwezi kamwe kuihariri. Ikiwa namba inaonekana si sahihi, rudisha fomu: mtu huyo anaarekebisha mwenyewe na kusaini tena, fomu yake iliyorekebishwa inachukua nafasi ya ile ya zamani, na fomu ya awali inabaki kwenye rekodi ikiwa na tarehe yake ya ubadilishaji.",
  "payroll.profile.ownerNote": "Haya ni maelezo yako mwenyewe yaliyo kwenye faili, kutoka kwa akaunti yako. Ni wewe tu unaweza kuyaona hapa — na kwa kuwa ni yako, unaweza kuyasasisha hapa hapa yanapobadilika.",
  "payroll.profile.edit": "Badilisha maelezo yako",
