  "staffLib.perm.staffClockBoard": "Ubao wa saa na kutoka kulikokosekana",
  "staffLib.perm.staffCallins": "Kuitwa kazini",
  "staffLib.area.clockAccess": "Ubao wa saa na kuitwa kazini",
  "staff.memberDialog.clockAccessHint": "Kwa mameneja tu — tiki mbili tofauti. Ubao wa saa na kutoka kulikokosekana humruhusu meneja huyu kuona rekodi za saa za timu na kusahihisha rekodi za muda kutoka ukurasa wa Wafanyakazi. Kuitwa kazini humruhusu meneja huyu kufungua madirisha ya kuitwa kazini, kumruhusu mtu kufanya kazi wakati hana zamu. Tiki hizi hazifanyi lolote kwa wafanyakazi.",
  "workforce.clockGate.closed": "Hujapangiwa kufanya kazi sasa, na hakuna dirisha la kuitwa kazini lililofunguliwa kwa ajili yako.",
  "workforce.clockGate.closedNext": "Hujapangiwa kufanya kazi sasa, na hakuna dirisha la kuitwa kazini lililofunguliwa kwa ajili yako. Zamu yako inayofuata inaanza {when}.",
