  "staff.callIn.title": "Kuitwa kazini na kutoka kazini kulikokosekana",
  "staff.callIn.desc": "Mwite mtu wakati hana zamu, na sahihisha rekodi za muda wakati kutoka kazini kuliposahaulika. Dirisha la kuitwa kazini hubaki wazi hadi mtu huyo atoke kazini.",
