  "apiErrors.clockGate.notScheduled": "Hujapangiwa kufanya kazi sasa, na hakuna dirisha la kuitwa kazini lililofunguliwa kwa ajili yako.",
  "apiErrors.clockAdmin.callinsNotGranted": "Mmiliki pekee, au meneja ambaye mmiliki amemwamini kwa kuitwa kazini, ndiye anayeweza kufanya hivyo.",
  "apiErrors.clockAdmin.boardNotGranted": "Mmiliki pekee, au meneja ambaye mmiliki amemwamini kwa ubao wa saa na kutoka kulikokosekana, ndiye anayeweza kufanya hivyo.",
  "apiErrors.clockAdmin.ownerOnlyForManager": "Mmiliki tu anaweza kusimamia wito wa kazini na rekodi za muda za meneja.",
  "apiErrors.clockFix.outBeforeIn": "Muda wa kutoka kazini lazima uwe baada ya muda wa kuingia kazini.",
  "apiErrors.clockFix.breakOutside": "Muda wa mapumziko lazima uwe kati ya muda wa kuingia kazini na muda wa kutoka kazini.",
  "apiErrors.clockFix.invalidTime": "Tuma kila muda kama tarehe na muda sahihi.",
  "apiErrors.notFound.timeEntryFound": "Rekodi ya muda haikupatikana.",
  "training.lessons.mgr-clock-callin.title": "Kuitwa kazini na masahihisho ya saa",
  "training.lessons.mgr-clock-callin.step1": "Mmiliki anaweza kumpa meneja tiki mbili tofauti. Kuitwa kazini hukuwezesha kufungua dirisha la kuitwa kazini kwa mfanyakazi, na Ubao wa saa na kutoka kulikokosekana hukuwezesha kuona ubao wa saa wa timu na kusahihisha rekodi za muda kutoka ukurasa wa Wafanyakazi. Kila tiki hufanya kazi yenyewe — meneja anaweza kuwa na moja bila nyingine.",
  "training.lessons.mgr-clock-callin.step2": "Dirisha la kuitwa kazini humruhusu mtu kuingia na kuanza kazi wakati hakuna zamu inayomfunika. Lifungue kutoka ukurasa wa Wafanyakazi, kwenye kadi ya Kuitwa kazini na kutoka kazini kulikokosekana.",
  "training.lessons.mgr-clock-callin.step3": "Dirisha hubaki wazi hadi mtu huyo atoke kazini — kisha hufuata muda wa kawaida wa dakika 10 kabla ya kutoka kwenye akaunti — au hadi wewe au mmiliki mlifunge mapema. Hakuna kinacholifunga chenyewe.",
  "training.lessons.mgr-clock-callin.step4": "Wakati mtu anasahau kutoka kazini, rekodi yake huwekwa alama kwenye ukurasa wa Wafanyakazi na katika Malipo ya Mishahara mara tu zamu iliyopangwa inapoisha, na wewe na mmiliki mnaarifiwa. Rekodi huendelea kuhesabu hadi isahihishwe.",
  "training.lessons.mgr-clock-callin.step5": "Sahihisha rekodi kutoka ukurasa wa Wafanyakazi: weka kuingia kazini, kutoka kazini, na muda wowote wa mapumziko. Meneja husahihisha rekodi za wafanyakazi tu — rekodi za meneja mwenyewe husahihishwa na mmiliki.",
  "staffLib.perm.staffDocuments": "Nyaraka za wafanyakazi",
  "staffLib.area.documentsAccess": "Nyaraka za wafanyakazi",
  "staff.memberDialog.documentsAccessHint": "Kwa mameneja pekee — kwa tiki hii, meneja huyu anaweza kufungua faili za nyaraka za wanachama wa wafanyakazi: karatasi zinazohifadhiwa kwa kila mtu, kama vile fomu za W-4, maombi ya kazi na nakala za vitambulisho. Utaombwa uthibitisho kwanza — faili hizi zina nambari za Hifadhi ya Jamii na tarehe za kuzaliwa. Tiki hii haifanyi chochote kwa wafanyakazi.",
  "staff.documentsWarning.body": "Mtu huyu ataweza kuona taarifa za siri kuhusu wanachama wa wafanyakazi wako, ikiwa ni pamoja na nambari za Hifadhi ya Jamii na tarehe za kuzaliwa.",
  "staff.documentsWarning.confirm": "Ndiyo, naelewa",
  "staff.documents.title": "Nyaraka za wafanyakazi",
  "staff.documents.desc": "Karatasi unazohifadhi kwa kila mtu — fomu za W-4, maombi ya kazi, fomu za kodi, nakala za vitambulisho. Ni wewe pekee, na meneja unayempa tiki ya Nyaraka za wafanyakazi, mnaoweza kufungua faili hizi.",
  "staff.documents.open": "Nyaraka",
  "staff.documents.fileCount": "{count} kwenye faili",
  "staff.documents.noneOnFile": "Hakuna kwenye faili",
  "staff.documents.dialogDesc": "Kila upakiaji huhifadhiwa — toleo jipya zaidi halichukui kamwe nafasi ya yale ya awali.",
  "staff.documents.titleLabel": "Kichwa",
  "staff.documents.titlePlaceholder": "W-4, ombi la kazi, nakala ya kitambulisho…",
