  "staff.documents.noFileChosen": "Hakuna faili iliyochaguliwa",
  "staff.documents.upload": "Ongeza nyaraka",
  "staff.documents.uploading": "Inaongezwa…",
  "staff.documents.empty": "Hakuna nyaraka kwenye faili kwa mtu huyu bado.",
  "staff.documents.uploadedBy": "Imepakiwa na {name}",
  "staff.documents.openFile": "Fungua",
  "staff.documents.remove": "Ondoa",
