  "nav.xstoreMessages": "Ujumbe Baina ya Maduka",
  "plansLib.businessIncludes.xstoreMessages": "Ujumbe Baina ya Maduka — timu yako yote, katika biashara zako zote",
  "xstore.title": "Ujumbe Baina ya Maduka",
  "xstore.help": "Kila mtu kwenye akaunti hii, kutoka biashara zako zote, katika kisanduku kimoja cha kupokea. Mtumie ujumbe yeyote kati yao hapa — maandishi au sauti, ukiwa na alama za kuwasilishwa na kusomwa. Ujumbe wa ndani ya duka lako unabaki kama ulivyo.",
  "xstore.empty": "Hakuna mazungumzo bado. Anzisha moja kwa Ujumbe mpya.",
  "xstore.noPeople": "Hakuna mtu mwingine wa kumtumia ujumbe bado. Watu huonekana hapa wanapojiunga na mojawapo ya biashara zako na kuingia.",
  "xstore.deliveredLabel": "Umewasilishwa",
  "apiErrors.planGated.crossStoreMessagesPartBusiness": "Ujumbe Baina ya Maduka ni sehemu ya mpango wa Business.",
  "apiErrors.invalidValue.personNotPartAccount": "Mtu huyo si sehemu ya akaunti hii.",
  "training.lessons.owner-xstore-messages.title": "Ujumbe katika maduka yako yote, kwa wamiliki",
  "training.lessons.owner-xstore-messages.step1": "Ujumbe Baina ya Maduka ni kisanduku cha pili cha kupokea, tofauti na Ujumbe. Ujumbe ni wa duka unalosimamia; mlango huu huwafikia kila mtu kwenye akaunti yako, katika kila biashara unayomiliki — hadi biashara tano.",
  "training.lessons.owner-xstore-messages.step2": "Fungua Ujumbe Baina ya Maduka kutoka kwenye menyu na uanzishe mazungumzo na yeyote aliye kwenye orodha. Orodha huonyesha kila mwanatimu kutoka biashara zako zote aliyeingia, pamoja na maduka wanayofanyia kazi.",
  "training.lessons.owner-xstore-messages.step3": "Picha huenda pamoja: kila mtu huonyesha picha yake ya wasifu iliyoidhinishwa, au herufi za kwanza za jina lake ikiwa hana. Kila ujumbe una tarehe na saa uliotumwa.",
  "training.lessons.owner-xstore-messages.step4": "Chini ya ujumbe wako mwenyewe unaweza kuona Umewasilishwa ujumbe unapofika, na Umesomwa mtu mwingine anapofungua mazungumzo. Vidokezo vya sauti pia hufanya kazi hapa, kama ilivyo katika Ujumbe.",
  "training.lessons.owner-xstore-messages.step5": "Mazungumzo hapa ni ya faragha kwa watu wawili walio ndani yake. Usimamizi wako wa Ujumbe wa ndani ya duka haufiki maduka mengine.",
  "training.lessons.mgr-xstore-messages.title": "Ujumbe katika maduka yako yote, kwa mameneja",
  "training.lessons.mgr-xstore-messages.step1": "Ujumbe Baina ya Maduka huwafikia kila mtu kwenye akaunti hii, katika kila biashara — si duka unalosimamia tu. Uko kwenye menyu, tofauti na Ujumbe.",
  "training.lessons.mgr-xstore-messages.step2": "Anzisha mazungumzo kutoka kwenye orodha: kila mwanatimu aliyeingia yupo, pamoja na maduka wanayofanyia kazi kando ya majina yao.",
  "training.lessons.mgr-xstore-messages.step3": "Tuma maandishi, au rekodi kidokezo cha sauti. Kabla ya kidokezo cha sauti kutumwa, unaweza kukisikiliza tena, kukitupa, au kukituma — kama ilivyo katika Ujumbe.",
  "training.lessons.mgr-xstore-messages.step4": "Ujumbe wako huonyesha Umewasilishwa unapofika na Umesomwa mtu mwingine anapofungua mazungumzo. Picha iliyo kando ya kila jina ni picha ya wasifu iliyoidhinishwa ya mtu huyo.",
  "training.lessons.staff-xstore-messages.title": "Ujumbe katika maduka yako yote",
  "training.lessons.staff-xstore-messages.step1": "Ujumbe Baina ya Maduka ni mahali unapoweza kumfikia yeyote kwenye akaunti hii, katika biashara yoyote ya mmiliki — swali kwa duka lingine halihitaji kusubiri tena.",
  "training.lessons.staff-xstore-messages.step2": "Ufungue kutoka kwenye menyu, uchague mtu, na uandike. Ikiwa mtu unayemhitaji hayupo kwenye orodha, bado hajaingia — ataonekana mara tu anapoingia.",
  "training.lessons.staff-xstore-messages.step3": "Unaweza pia kutuma vidokezo vya sauti hapa: rekodi, sikiliza tena, kisha tuma au tupa. Kila ujumbe huonyesha tarehe na saa uliotumwa.",
  "training.lessons.staff-xstore-messages.step4": "Unapotuma ujumbe, huonyesha Umewasilishwa unapofika, na Umesomwa mtu mwingine anapofungua mazungumzo. Mazungumzo ni ya faragha kwako na mtu mwingine.",
