  "plansLib.businessIncludes.restaurantOps": "Shughuli za mgahawa — ankara za wasambazaji zenye ulinganishaji wa njia tatu, kumbukumbu ya taka, tarehe za kumalizika muda na jedwali la vizio",
  "plansLib.businessIncludes.restaurantDaily": "Zana za kila siku za mgahawa — kumbukumbu za joto, ubao wa vilivyoisha, karatasi za maandalizi, uchambuzi wa menyu, tofauti na uhamishaji wa uhasibu",
  "plansLib.businessIncludes.restaurantKitchen": "Mgahawa, Jikoni na mapishi — mapishi yenye upunguzaji wa viungo kiotomatiki na gharama za kweli za vyakula, karatasi za maandalizi, uzalishaji wa makundi na uchambuzi wa menyu",
  "plansLib.businessIncludes.restaurantStock": "Mgahawa, Hisa na maagizo — viwango vya par, mwongozo wa maagizo kwa wasambazaji na uhamishaji kati ya maeneo, pamoja na karatasi za kuhesabu kwa mpangilio wa rafu",
  "plansLib.businessIncludes.restaurantMoney": "Mgahawa, Ankara na fedha — ankara za wasambazaji zenye ulinganishaji wa njia tatu, arifa za bei, tofauti na uhamishaji wa uhasibu, pamoja na memo za mkopo za wasambazaji",
  "plansLib.businessIncludes.restaurantSafety": "Mgahawa, Usalama wa chakula — kumbukumbu za joto, tarehe za kumalizika muda kwa mpangilio wa kinachoisha kwanza kitumike kwanza, lebo za tarehe na jedwali la vizio, na kumbukumbu za joto zilizojazwa kwa faili ya usalama wa chakula",
  "plansLib.businessIncludes.restaurantFloor": "Mgahawa, Sakafu na wageni — ubao wa vilivyoisha na kumbukumbu ya taka",
  "plansLib.businessIncludes.restaurantTeam": "Mgahawa, Timu na mahali — chakula cha wafanyakazi",
