  "exportsLib.restaurantLedger.title": "Daftari la mgahawa",
  "exportsLib.restaurantLedger.description": "Ununuzi uliopokelewa, taka, milo ya wafanyakazi na matumizi ya mapishi katika daftari moja: sehemu, tarehe, bidhaa, kiasi, gharama ya kipimo, jumla ya gharama na rejeo.",
