  "training.lessons.owner-restaurant-ops.title": "Shughuli za mgahawa, kwa wamiliki",
  "training.lessons.owner-restaurant-ops.step1": "Ankara za wasambazaji ziko katika kona ya Mgahawa. Ingiza kile msambazaji alichotoza, kikiwa kimeunganishwa na agizo lake la ununuzi, na programu huikagua kwa njia tatu — kilichoagizwa, kilichopokelewa na kilichotozwa, bega kwa bega — na huashiria mstari wowote ulio mfupi, uliozidi, au uliotozwa kwa bei tofauti.",
  "training.lessons.owner-restaurant-ops.step2": "Mstari wa ankara ukitoza bidhaa kwa bei tofauti na gharama iliyorekodiwa, arifa ya bei hufunguka kwenye ukurasa wa ankara. Kukubali arifa husasisha gharama ya bidhaa hadi bei iliyotozwa; kuiondoa huacha gharama kama ilivyokuwa.",
  "training.lessons.owner-restaurant-ops.step3": "Kumbukumbu ya taka hurekodi kila kitu jiko linachotupa, kwa sababu — kuharibika, kuzalisha kupita kiasi, kosa la maandalizi, kurejeshwa, kumwagika, au nyingine — na kuiandika huondoa akiba rafuni yenyewe. Makundi ya kumalizika muda yameorodheshwa kinachoisha kwanza, kitumike kwanza, ili tarehe ya mwisho ya matumizi ya mapema zaidi itumike kwanza, na unaweza kuchapa lebo za tarehe kwa makundi unayoteua.",
  "training.lessons.owner-restaurant-ops.step4": "Jedwali la vizio huhesabu vizio vya kila sahani kutokana na viungo vya mapishi yake, dhidi ya vizio vikuu tisa, ili swali la mgeni lijibiwe kutokana na rekodi, si kwa kumbukumbu ya kichwa. Kumbukumbu za joto, ubao wa vilivyoisha na milo ya wafanyakazi vimefunguliwa kwa timu nzima — hakuna kibali kinachohitajika — kwa sababu uandikaji wa kila siku hufanya kazi tu pale kila mtu anapoweza kuufanya.",
  "training.lessons.owner-restaurant-ops.step5": "Uchambuzi wa menyu huweka kila sahani kwa kiasi ilichouza na kiasi ilichoingiza: nyota, farasi wa kulima, mafumbo na mbwa. Ukurasa wa tofauti hulinganisha kile mapishi yanasema kilichopaswa kuondoka rafuni dhidi ya milo ya wafanyakazi, taka na kila kingine kilichotoka — kilichobaki hakina maelezo. Uhamishaji wa uhasibu hukusanya ununuzi uliopokelewa, taka, milo ya wafanyakazi na matumizi ya mapishi katika daftari moja kwa vitabu vyako.",
  "training.lessons.staff-restaurant-daily.title": "Tabia za kila siku za jiko",
  "training.lessons.staff-restaurant-daily.step1": "Kitu kikitupwa, kiandike kwenye kumbukumbu ya taka siku hiyo hiyo: kilikuwa nini, kiasi gani, na sababu — kuharibika, kuzalisha kupita kiasi, kosa la maandalizi, kurejeshwa, kumwagika, au nyingine. Kuiandika huondoa akiba rafuni yenyewe; hurekebishi akiba kando.",
  "training.lessons.staff-restaurant-daily.step2": "Andika kila joto la jokofu, friza na kuhifadhi moto unapolichunguza. Kumbukumbu huhifadhi jina lako na muda, na huashiria kipimo chochote kilicho nje ya kiwango salama — andika ulichofanya kuhusu hilo kama hatua ya kurekebisha.",
  "training.lessons.staff-restaurant-daily.step3": "Ubao wa vilivyoisha ni kile kilichoisha, sasa hivi. Bandika bidhaa wakati inapokuisha, ili timu nzima ijue mara moja, na iondoe inapopatikana tena — ubao huhifadhi nani aliyeiondoa na lini.",
  "training.lessons.staff-restaurant-daily.step4": "Timu ikila, irekodi kama mlo wa wafanyakazi. Kila mlo huondoa sahani yake rafuni na hutumia viungo vya mapishi ya sahani, kama uuzaji. Mlo wa mfanyakazi ni gharama halisi ya siku, na unapaswa kuwa kwenye rekodi.",
  "training.lessons.mgr-restaurant-invoices.title": "Ankara, makundi na uzalishaji wa makundi",
  "training.lessons.mgr-restaurant-invoices.step1": "Mmiliki amekuamini kwa kibali cha Kujenga mapishi, na pia hufungua kazi ya ujenzi ya jiko: ankara za wasambazaji, makundi ya kumalizika muda na uzalishaji wa makundi. Ingiza ankara ya msambazaji na mistari yake — bidhaa, kiasi na gharama iliyotozwa — na uiunganishe na agizo lake la ununuzi likiwapo.",
  "training.lessons.mgr-restaurant-invoices.step2": "Agizo la ununuzi likiunganishwa, ankara hukaguliwa kwa njia tatu, mstari kwa mstari: kilichoagizwa, kilichopokelewa na kilichotozwa. Mstari unaweza kurudi ukilingana, ukiwa mfupi, ukizidi, ukitozwa kwa bei tofauti, au usiwe kwenye agizo kabisa.",
  "training.lessons.mgr-restaurant-invoices.step3": "Bei iliyotozwa ikitofautiana na gharama ya bidhaa iliyorekodiwa, arifa ya bei hufunguka. Kukubali arifa huweka gharama ya bidhaa kwa bei mpya iliyotozwa; kuiondoa hakubadilishi chochote. Arifa moja tu iliyo wazi husimama kwa ankara na bidhaa ile ile kwa wakati mmoja.",
  "training.lessons.mgr-restaurant-invoices.step4": "Pokea akiba kama kundi la kumalizika muda lenye tarehe yake ya mwisho ya matumizi, na ukurasa wa kumalizika muda huweka makundi kinachoisha kwanza, kitumike kwanza. Uzalishaji wa kundi hutengeneza mapishi mara kadhaa zilizowekwa: hutumia viungo vya mapishi na huweka bidhaa ya maandalizi iliyokamilika rafuni — mapishi lazima yaunganishwe na bidhaa hiyo ya maandalizi kwanza.",
  "training.lessons.mgr-restaurant-invoices.step5": "Msambazaji anaporudisha pesa dhidi ya ankara — katoni iliyoharibika, uwasilishaji mfupi, bei iliyosahihishwa — irekodi kama memo ya mkopo kwenye ukurasa wa ankara, dhidi ya ankara hiyo. Msambazaji hutoka kwenye ankara yenyewe, na memo huhesabiwa dhidi ya kile ankara bado inadaiwa: ankara inaonyesha mkopo wake uliotumika na salio lake linalodaiwa. Mkopo hauwezi kamwe kuzidi ankara yake, na kubatilisha memo huiweka kwenye rekodi huku ikiacha kuhesabiwa. Chapisha memo kutoka kwenye safu yake unapoihitaji kwenye karatasi — karatasi iliyochapishwa ni rekodi yako mwenyewe ya mkopo wa msambazaji, si hati ya msambazaji.",
  "training.lessons.mgr-restaurant-reports.title": "Uchambuzi wa menyu, tofauti na vitabu",
  "training.lessons.mgr-restaurant-reports.step1": "Mmiliki amekuamini kwa kibali cha Pesa za sahani, na pia hufungua ripoti za pesa za jiko: uchambuzi wa menyu, tofauti na uhamishaji wa uhasibu. Takwimu hizi hubaki ndani ya biashara, kama pesa zote za sahani.",
  "training.lessons.mgr-restaurant-reports.step2": "Uchambuzi wa menyu huweka kila sahani kwa kiasi ilichouza na kiasi ilichoingiza katika kipindi. Nyota huuza vizuri na huingiza vizuri; farasi wa kulima huuza vizuri lakini huingiza kidogo; mafumbo huingiza vizuri lakini huuza kidogo; mbwa hawafanyi lolote kati ya hayo.",
  "training.lessons.mgr-restaurant-reports.step3": "Ukurasa wa tofauti hufanya kazi kwa kila bidhaa: kile mapishi yanasema kilichopaswa kuondoka rafuni, kando ya milo ya wafanyakazi, taka na kila utokaji mwingine wa akiba. Kilichobaki hakina maelezo — na kisicho na maelezo ndiyo nambari ya kwenda kueleza.",
  "training.lessons.mgr-restaurant-reports.step4": "Uhamishaji wa uhasibu ni daftari moja kwa jiko: ununuzi uliopokelewa, taka, milo ya wafanyakazi na matumizi ya mapishi, kila safu ikiwa na tarehe yake, kiasi na gharama, tayari kukabidhi kwa yeyote anayeshika vitabu vyako.",
