  "storefronts.ebayDesc": "Unganisha duka lako la eBay mara moja. Bidhaa inachouza kwenye eBay, idadi yake hupungua hapa yenyewe, huku mauzo yakirekodiwa katika mienendo yako — sawa na kama ingekuwa imeskaniwa kutoka. Mauzo hutiririka upande mmoja tu: kutoka eBay kwenda kwenye programu.",
