  "storefronts.notAvailableBody": "Mmiliki wa programu hajaongeza funguo za eBay bado, kwa hivyo mlango huu hauwezi kufunguka. Kila kitu kingine kwenye ukurasa huu kiko tayari — angalia tena mara funguo zitakapowekwa.",
  "storefronts.notAvailableTitle": "Miunganisho ya eBay haijawashwa bado",
