  "storefronts.recentTitle": "Mauzo ya hivi karibuni ya eBay",
  "storefronts.skuLabel": "SKU",
  "storefronts.staffNote": "Mmiliki au meneja hutunza muunganisho huu. Unaweza kuona jinsi unavyoendelea hapa.",
  "storefronts.subtitle": "Unganisha duka la mtandaoni mara moja, na mauzo yake husasisha hisa zako yenyewe.",
  "storefronts.title": "Miunganisho ya maduka ya mtandaoni",
  "training.lessons.owner-ebay-connect.step1": "Fungua Miunganisho ya maduka ya mtandaoni (katika kikundi cha Mauzo) na uguse Unganisha eBay. Unaingia kwenye ukurasa wa eBay wenyewe — programu haioni kamwe nenosiri lako la eBay.",
  "training.lessons.owner-ebay-connect.step2": "Duka moja la eBay huunganishwa na biashara moja — biashara ambayo bidhaa zake duka hilo huuza. Ikiwa unaendesha biashara zaidi ya moja, unganisha kila duka na biashara yake yenyewe.",
  "training.lessons.owner-ebay-connect.step3": "Chagua eneo ambalo hisa zako za eBay ziko, ili mauzo yatoke kwenye rafu sahihi.",
  "training.lessons.owner-ebay-connect.step4": "Kuanzia hapo, mauzo hutua yenyewe: bidhaa inachouza kwenye eBay, idadi yake hupungua hapa na mauzo hurekodiwa katika Mienendo pamoja na nambari ya agizo la eBay. Hakuna kinachotiririka kurudi — programu haibadilishi kamwe orodha zako za eBay.",
  "training.lessons.owner-ebay-connect.step5": "Mauzo huoanishwa kwa SKU, UPC, au ISBN kwenye orodha — yoyote kati ya hizo tatu ambayo orodha hubeba. Ikiwa mauzo hayawezi kuoanishwa, husubiri chini ya 'Mauzo yanayohitaji kuoanishwa' kwenye ukurasa wa Miunganisho ya maduka ya mtandaoni: iunganishe na bidhaa yake mara moja, na mauzo hayo — na yajayo kama hayo — hujirekodi yenyewe. 'Angalia mauzo sasa' huleta chochote cha hivi karibuni, na Tenganisha husimamisha muunganisho; mauzo yaliyokwisha kurekodiwa hubaki.",
  "training.lessons.owner-ebay-connect.title": "Unganisha duka lako la eBay",
  "training.module.storefronts": "Miunganisho ya maduka ya mtandaoni",
